import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易集注 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易集注 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/016.md","filePath":"zh/classics/jizhu/016.md"}'),h={name:"zh/classics/jizhu/016.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>否者闭塞不通也，卦象卦德皆与泰反。《序卦》“物不可以终通，故受之以否”，所以次泰。此七月之卦。</p><p>否之匪人，与履虎尾同人于野艮其背同例，卦辞惟此四卦与卦名相连。否之匪人者，言否之者非人也，乃天也，即大往小来也。不利者，即彖辞，万物不通，天下无邦，道长道消也。君子贞者，即俭德避难，不可荣以禄也。不言小人者，易为君子谋也。大往小来者，否泰相综，泰内卦之阳，往而居否之外，外卦之阴，来而居否之内也。文王当殷之末世，亲见世道之否，所以发匪人之句。后来孔子居春秋之否，乃曰道之将行也与命也，道之将废也与命也。孟子居战国之否，乃曰莫之为而为者天也，莫之致而致者命也，皆宗文王否之匪人之句。否之匪人者天数也，君子贞者人事也，所以孔孟进以礼，退以义，惟守君子之贞。程朱以为非人道也，似无道字意。诚斋以为用非其人，似无用字意。不如只就大往小来说。</p><p>言否之者非人也，乃天也。否由于天，所以占者不利。丁否运之君子，欲济其否，岂容智力于间哉，惟当守其正而已。何也?大往小来，匪人也，乃天运之自然也。天运既出于自然，君子亦将为之何哉!故惟当守其正而已。</p><p>《彖》曰：否之匪人，不利，君子贞。大往小来，则是天地不交，而万物不通也。上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。</p><p>释大往小来四字，与泰卦同。上自为上，下自为下，则虽有国，实与无邦国同矣，故天下无邦。</p><h3 id="《象》曰-天地不交-否。君子以俭德辟难-不可荣以禄。-辟音避-难去声" tabindex="-1">《象》曰：天地不交，否。君子以俭德辟难，不可荣以禄。(辟音避，难去声) <a class="header-anchor" href="#《象》曰-天地不交-否。君子以俭德辟难-不可荣以禄。-辟音避-难去声" aria-label="Permalink to “《象》曰：天地不交，否。君子以俭德辟难，不可荣以禄。(辟音避，难去声)”">​</a></h3><p>俭者，俭约其德，敛其首先之光也。坤为吝啬，俭之象也。辟难者，避小人之祸也。三阳出居在外，避难之象也。不可荣以禄者，人不可得而荣之以禄也，非戒辞也。言若不俭德，则人因德而荣禄，小人忌之，祸即至矣。今既俭德，人不知我，则不荣以禄，故不禁以禄者，正所以避难也。</p><p>初六，拔茅茹，以其汇，贞吉亨。</p><p>变震为蕃，茅茹之象也。否综泰，故初爻辞同。贞者，上有九五刚健中正之君，三阴能牵连而志在于君则贞矣。盖否之时，能从乎阳，是小人能从君子，岂不贞。</p><p>初在下，去阳甚远，三阴同体，故有拔茅茹以其汇之象。当否之时，能正而志在于休否之君，吉而且亨之道也，故教占者以此。</p><h3 id="《象》曰-拔茅贞吉-志在君也。" tabindex="-1">《象》曰：拔茅贞吉，志在君也。 <a class="header-anchor" href="#《象》曰-拔茅贞吉-志在君也。" aria-label="Permalink to “《象》曰：拔茅贞吉，志在君也。”">​</a></h3><p>贞者以其志在于君也，故吉。泰初九曰志在外，此变外为君者，泰六五之君，不如否之刚健中正，得称君也。</p><p>六二，包承，小人吉，大人否亨。</p><p>包承者，包乎初也。二乃初之承，曰包承者，犹言将承包之也。大来乎下，故曰包荒，小来乎下，故曰包承。既包乎承，则小人与小人为群矣。小人与小人为群，大人与大人为群，不相干涉，不相伤害矣。否者不荣以禄也。</p><p>当否之时，小来乎下，故六二有包承之象。既包乎承，则小人为群，不上害乎大人矣，故占者在小人则有不害正之吉，在大人则身否而道亨也。</p><h3 id="《象》曰-大人否亨-不乱群也。" tabindex="-1">《象》曰：大人否亨，不乱群也。 <a class="header-anchor" href="#《象》曰-大人否亨-不乱群也。" aria-label="Permalink to “《象》曰：大人否亨，不乱群也。”">​</a></h3><p>阴来乎下，阳往乎上，两不相交，故不乱群。</p><p>六三，包羞。</p><p>包者，包乎二也。三见二包乎其初，三即包乎二，殊不知二隔乎阳，故包同类，若三则亲比乎阳矣。从阳可也，乃不从阳，非正道矣，可羞者也，故曰包羞。</p><p>六三不中不正，亲比乎阳，当小来于下之时，止知包乎其下矣，而不知上有阳刚之大人在也，乃舍四之大人而包二之小人，羞孰甚焉，故有是象。占者之羞可知矣。</p><h3 id="《象》曰-包羞-位不当也。" tabindex="-1">《象》曰：包羞，位不当也。 <a class="header-anchor" href="#《象》曰-包羞-位不当也。" aria-label="Permalink to “《象》曰：包羞，位不当也。”">​</a></h3><p>位不当者，柔而志刚，不能顺从乎君子，故可羞。</p><p>九四，有命无咎，畴离祉。</p><p>变巽为命，命之象也。有命者，受九五之命也。四近君，居多惧之地，易于获咎。今变巽顺，则能从乎五矣，故有命无咎。畴者，同类之三阳也。离者丽也，离祉者，附丽其福祉也。</p><p>九四当否过中之时，刚居乎柔，能从休否之君，同济乎否，则因大君之命，而济否之志行矣。故不惟在我无咎，获一身之庆，而同类亦并受其福也。故其象占如此。</p><h3 id="《象》曰-有命无咎-志行也。" tabindex="-1">《象》曰：有命无咎，志行也。 <a class="header-anchor" href="#《象》曰-有命无咎-志行也。" aria-label="Permalink to “《象》曰：有命无咎，志行也。”">​</a></h3><p>济否之志行。</p><p>九五，休否，大人吉。其亡其亡，系于苞桑。</p><p>休否者，休息其否也。其亡其亡者，念念不忘其亡，惟恐其亡也。人依木息曰休，中爻巽木，五居木之上，休之象也。巽为阴木，二居巽之下，阴木柔，桑之象也。巽为绳，系之象也。丛生曰苞，丛者聚也。柔条细弱，群聚而成丛者也。此爻变离合坎，为丛棘，苞之象也。桑止可取叶养蚕，不成其木已，非樟楠松柏之大矣，又况丛聚而生，则至小而至柔者也。以国家之大，不系于磐石之坚固，而系于苞桑之柔小，危之甚也，即危如累卵之意。此二句有音韵，或古语也。</p><p>九五阳刚中正，能休时之否，大人之事也，故大人遇之则吉。然下应乎否，惟休否而已，未倾否也，故必勿恃其否之可休，勿安其休之为吉。兢业戒惧，念念惟恐其亡，若国家系于苞桑之柔小，常畏其亡，而不自安之象，如此则否休而渐倾矣。故教占者，必儆戒如此，系于苞桑，又其亡其亡之象也。</p><h3 id="《象》曰-大人之吉-位正当也。" tabindex="-1">《象》曰：大人之吉，位正当也。 <a class="header-anchor" href="#《象》曰-大人之吉-位正当也。" aria-label="Permalink to “《象》曰：大人之吉，位正当也。”">​</a></h3><p>有中正之德而又居尊位，与夬履同者，亦恐有所恃，故爻辞有其亡其亡之句。</p><p>上九，倾否，先否后喜。</p><p>上文言休息其否，则其否犹未尽也。倾者倒也，与鼎之颠趾同言颠倒也。本在下，而今反在上也。否泰乃上下相综之卦，泰阴上阳下，泰终则复隍，阳反在上，而否矣。否，阳上阴下，否终则倾倒，阴反在上而泰矣，此倾字之意也。复隍复字，应无往不复复字。倾否倾字，应无平不陂陂字。陂者倾邪也，周公爻辞，其精极矣。变兑成悦，喜之象也。</p><p>上九以阳刚之才，居否之终，倾时之否，乃其优为者，故其占为先否后喜。</p><h3 id="《象》曰-否终则倾-何可长也。" tabindex="-1">《象》曰：否终则倾，何可长也。 <a class="header-anchor" href="#《象》曰-否终则倾-何可长也。" aria-label="Permalink to “《象》曰：否终则倾，何可长也。”">​</a></h3><p>言无久否之理。</p>',38)])])}const m=e(h,[["render",t]]);export{_ as __pageData,m as default};
